/**
 * Parse the environment layer, a `NAME=VALUE` line per variable.
 * @param {string} text - the whole text read from standard input.
 * @param {(name: string) => string | undefined} keyOf - the setting one variable name carries, if any.
 * @returns {Map<string, {text: string, line: number, column: number}>} each setting key's raw value
 *   and the position it was written at, in the order the input writes them.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parseEnv(text, keyOf) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const seen = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new IniError(line, indent(raw), 'expected a variable name')
    const key = keyOf(name)
    if (key === undefined) throw new IniError(line, indent(raw), `unknown environment variable ${name}`)
    if (seen.has(name)) throw new IniError(line, indent(raw), `${name} is set twice`)
    seen.add(name)
    values.set(key, { text: trimmed.slice(split + 1).trim(), line, column: valueColumn(raw, split) })
  }
  return values
}"}

