/** One refusal of a value that does not fit its declared type. */
export class TypeError_ extends Error {}

const UNITS = { ms: 1, s: 1000, m: 60000, h: 3600000 }
const INTEGER = /^(0|-?[1-9][0-9]*)$/u
const DURATION = /^([0-9]+)(ms|s|m|h)$/u

/**
 * Coerce one setting's raw text by its declared type.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text the winning layer wrote.
 * @returns {string} the rendering of the coerced value.
 * @throws {TypeError_} when the text does not fit the type.
 */
export function coerce(declared, text) {
  const { key, type } = declared
  if (type === 'string') return text
  if (type === 'integer') {
    if (!INTEGER.test(text)) throw new TypeError_(`${key} is not an integer: ${text}`)
    return text
  }
  if (type === 'boolean') {
    if (text !== 'true' && text !== 'false') throw new TypeError_(`${key} is not a boolean: ${text}`)
    return text
  }
  if (type === 'enum') {
    const members = declared.members ?? []
    if (!members.includes(text)) throw new TypeError_(`${key} is not one of ${members.join('|')}: ${text}`)
    return text
  }
  if (type === 'duration') {
    const match = DURATION.exec(text)
    if (match === null) throw new TypeError_(`${key} is not a duration: ${text}`)
    return String(Number(match[1]) * UNITS[match[2]])
  }
  if (type === 'list') {
    if (text === '') return ''
    const items = []
    for (const item of text.split(',')) {
      const trimmed = item.trim()
      if (trimmed === '') throw new TypeError_(`${key} has an empty item: ${text}`)
      if (!items.includes(trimmed)) items.push(trimmed)
    }
    return items.join(',')
  }
  return text
}"}

