    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** The environment layer, read from standard input and refused at its own position. */
function envLayer() {
  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }
  try {
    return { name: 'env', source: '<stdin>', values: parseEnv(text, keyOfVariable) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

/** Refuse a key the layer sets and the schema does not know, in the order the layer writes them. */
function checkKnown(layer) {
  for (const [key, entry] of layer.values) {
    if (setting(key) === undefined) {
      fail(`${layer.source}:${entry.line}:${entry.column}: unknown setting ${key}`)
    }
  }
  return layer
}

/** The three layers of a layered mode, each read and checked before the next one is read. */
function stack(base, site) {
  const layers = []
  layers.push(checkKnown(iniLayer('base', base)))
  layers.push(checkKnown(iniLayer('site', site)))
  layers.push(envLayer())
  return merge(layers)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []
if (mode === 'load' || mode === 'origin') {
  const values = stack(argv[1], argv[2])
  if (mode === 'origin') {
    for (const declared of SETTINGS) {
      const entry = values.get(declared.key)
      out.push(`${declared.key} ${entry === undefined ? 'default' : entry.layer}`)
    }
  } else {
    for (const declared of SETTINGS) {
      const entry = values.get(declared.key)
      const text = entry === undefined ? declared.default : entry.text
      try {
        out.push(`${declared.key}=${coerce(declared, text)}`)
      } catch (error) {
        if (!(error instanceof ValueError)) throw error
        fail(entry === undefined ? error.message : `${entry.where}: ${error.message}`)
      }
    }
  }
} else {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
